INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(99800, 'ruRU', '', 'Ах, вновь пылать силой!', 24330),
(99801, 'ruRU', '', 'Мой разум пылает. Я восстановлен.', 24330),
(99802, 'ruRU', '', 'Я переполнен силой!', 24330),
(99804, 'ruRU', '', 'Это чувство... возвращается ко мне... Я жив!', 24330),
(99826, 'ruRU', '', '$n! Ты и твои охотники на демонов — ничто.', 24330),
(99827, 'ruRU', '', 'Этот краеугольный камень доверил мне сам Саргерас. Он тебе не достанется!', 24330),
(99829, 'ruRU', '', 'Поспеши. Кейн уже начал атаку на Тиранну.', 24330),
(99831, 'ruRU', '', 'Твоя мерзкая магия тщетна, чудовище! Эти письмена под моей защитой.', 24330),
(99832, 'ruRU', '', 'Прочь, чудовище!', 24330),
(99833, 'ruRU', '', 'Сдавайся! Ты лишь бьёшь по ветру!', 24330),
(99837, 'ruRU', '', 'Удачи вам всем. Я подниму туда остальных, $n.', 24330),
(99838, 'ruRU', '', 'Спасибо, друг! Мои ученики погибли, защищая эти свитки. Могли быть потеряны века истории!', 24330),
(99839, 'ruRU', '', 'На нашу гавань пало проклятие.$B$BЧайки падают с неба, как камни. На днях я видел, как одна упала прямо на голову матроса. Вырубила его начисто.$B$BКосяки рыбы гниют брюхом кверху на отмелях. У наших рыбаков уже неделями нет приличного улова, а вонь от дохлой рыбы просто ужасна.$B$BЯ взял на себя дополнительные смены в башне, ведь большинство моих дозорных пропали без вести. Здесь наверху я нахожу передышку — мерзкий запах и спёртый воздух не так удушают.$B$BГавань мертва. Туман выдавил из неё саму жизнь.', 24330),
(99844, 'ruRU', '', 'Когда Даргрул украл Молот Хаз''горота, он сделал это прямо у меня на глазах и на глазах других вождей.', 24330),
(99845, 'ruRU', '', 'Наш последний верховный вождь, Улан, попытался остановить его и был убит. Майла, может, и подняла тотем отца, но она ещё не верховный вождь.', 24330),
(99846, 'ruRU', '', 'Даргрул не просто украл молот, он раздробил наш народ, вбив клин между нашими племенами.', 24330),
(99847, 'ruRU', '', 'Чэнь Буйный Портер обучал группу молодёжи, когда началась атака. Он один из сильнейших монахов, кого я знаю, но даже он не продержится вечно. Идём, нужно их спасти!', 24330),
(99849, 'ruRU', '', 'Настало время вознесения. Приготовьтесь; Один ждёт вашего прибытия.', 24330),
(99855, 'ruRU', '', 'Годами нас сторонились, Стражи изгнали нас в темнейшие глубины мира.\n\nТеперь нам предстоит справиться с труднейшим испытанием, какое только видел наш мир. Теперь мы должны защитить Азерот от его величайших врагов.', 24330),
(99857, 'ruRU', '', 'Было непросто, но мне удалось собрать немного оружия и припасов. Что тебе нужно?', 24330),
(99868, 'ruRU', '', '[Placeholder Event] - Sylvanas welcomes you to the Horde.', 24330),
(99877, 'ruRU', '', '|TInterface\\Icons\\INV_Enchant_EssenceArcaneSmall:20|t%s нацеливает на |cFFFF0000$n|r массивную |cFFFF0000|Hspell:192708|h[Тайную бомбу]|h|r!', 24330),
(99889, 'ruRU', '', '|TInterface\\Icons\\ability_shawaterelemental_swirl:20|t|cFFFF0000|Hspell:192696|h[Неистовые бури]|h|r начинаются, пока нет врагов в ближнем бою!', 24330),
(99901, 'ruRU', '', 'Не пойдёт! У нас нет времени прорубаться через эту орду!', 24330),
(99919, 'ruRU', '', 'Постарайся быть не столь заметным. Наблюдение даёт узнать гораздо больше, чем бой с врагом.', 24330),
(99943, 'ruRU', '', 'ВСЁ БУДЕТ ИСТРЕБЛЕНО!', 24330),
(99944, 'ruRU', '', 'ВОДА... ВЕЧНА...', 24330),
(99945, 'ruRU', '', 'СМЫТО ПРОЧЬ.', 24330),
(99946, 'ruRU', '', 'РАЗОРВАНО НА ЧАСТИ.', 24330),
(99947, 'ruRU', '', 'СОКРУШИТЬ!', 24330),
(99948, 'ruRU', '', 'УТОПИТЬ!', 24330),
(99949, 'ruRU', '', 'БУРЯ!', 24330),
(99950, 'ruRU', '', 'ШТОРМ ПРОБУЖДАЕТСЯ.', 24330),
(99956, 'ruRU', '', 'ИЩУ... МАГИЮ...', 24330),
(99957, 'ruRU', '', 'ТАЙНУЮ... ЭНЕРГИЮ...', 24330),
(99960, 'ruRU', '', '[PLACEHOLDER - In this quest you walk around the boat with me while I explain my evil plan.]', 24330),
(99961, 'ruRU', '', '[PLACEHOLDER - Did I say evil? I didn''t mean that. Forget you heard anything. You are queued for the scenario. Now listen to this awesome exposition.]', 24330),
(99962, 'ruRU', '', 'Привет! Интересуешься обучением изготовлению кожаных изделий?', 24330),
(99964, 'ruRU', '', 'О да, мы как раз на днях получили партию товара. Думаю, она всё ещё наверху, если хочешь сходить забрать.', 24330),
(99971, 'ruRU', '', '[PLACEHOLDER - In this quest we walk around the ship while I explain the mission.]', 24330);
